    _fields_ = [('data', ctypes.POINTER(ctypes.POINTER(gsl_complex))), ('tdim1', ctypes.c_size_t), ('tdim2', ctypes.c_size_t), ('tsize', ctypes.c_size_t), ('stride', ctypes.c_size_t)]

class gsl_vector_complex(ctypes.Structure):
    _fields_ = [('data', ctypes.POINTER(gsl_complex)), ('size', ctypes.c_size_t), ('stride', ctypes.c_size_t)]

