def numpy_to_gsl_matrix_complex(np_array):
    n = np_array.shape[0]
    m = np_array.shape[1]
    mat = gsl_matrix_complex()
    mat.tdim1 = n
    mat.tdim2 = m
    mat.data = (ctypes.POINTER(gsl_complex) * n)()
