from ctypes import c_double, c_void_p, CFUNCTYPE, POINTER

c_double = ctypes.c_double
c_void_p = ctypes.c_void_p

class GSLFunction:
    def __init__(self, func):
        self.func = func

    def get_c_func(self):
        def wrapper(x, params):
            return self.func(x)
        return CFUNCTYPE(c_double, c_double, c_void_p)(wrapper)

def integrate(func, a, b):
    # Load GSL libraries
    ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
    gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

    # Define gsl_function struct
    class gsl_function(ctypes.Structure):
        _fields_ = [
            ("function", ctypes.CFUNCTYPE(c_double, c_double, c_void_p)),
            ("params", c_void_p)
        ]

    # Define the GSL integration function
    gsl_integration_qk31 = gsl.gsl_integration_qk31
    gsl_integration_qk31.argtypes = [POINTER(gsl_function), c_double, c_double, POINTER(c_double), POINTER(c_double)]
    gsl_integration_qk31.restype = ctypes.c_int

    # Create the GSL function wrapper
    gsl_func = gsl_function()
    gsl_func.function = GSLFunction(func).get_c_func()
    gsl_func.params = None

    result = c_double()
    abserr = c_double()

    # Call the GSL function
    status = gsl_integration_qk31(ctypes.pointer(gsl_func), a, b, ctypes.byref(result), ctypes.byref(abserr))

    if status != 0:
        raise Exception("Integration failed")

    return (result.value, abserr.value, 0.0, 0.0)

