class GSLVector:
    def __init__(self, size):
        self.ptr = gsl.gsl_vector_alloc_n(size)
        if not self.ptr:
            raise RuntimeError("Failed to allocate vector")

    def set(self, index, value):
        gsl.gsl_vector_set(self.ptr, index, value)

    def get(self, index):
        return gsl.gsl_vector_get(self.ptr, index)

    def free(self):
        gsl.gsl_vector_free(self.ptr)

def create_and_manipulate_vector(values):
    if not values:
        return []
    vec = GSLVector(len(values))
    for i, val in enumerate(values):
        vec.set(i, val)
    result = [vec.get(i) for i in range(len(values))]
    vec.free()
    return result

