class GSLMatrix:
    def __init__(self, matrix):
        self._matrix = matrix
        self.rows = matrix.size1
        self.cols = matrix.size2


def list_to_gsl_matrix(matrix):
    rows = len(matrix)
    cols = len(matrix[0]) if rows > 0 else 0
    matrix_gsl = gsl.gsl_matrix_complex_alloc(rows, cols)
    data = ctypes.cast(matrix_gsl.data, ctypes.POINTER(gsl_complex))
    for i in range(rows):
        for j in range(cols):
            z = matrix[i][j]
            idx = i * cols + j
            data[idx].real = z.real
            data[idx].imag = z.imag
    return GSLMatrix(matrix_gsl)


def add_matrices(matrix_a, matrix_b):
    if matrix_a.rows != matrix_b.rows or matrix_a.cols != matrix_b.cols:
        raise ValueError("Matrices dimensions do not match")
    result = GSLMatrix(gsl.gsl_matrix_complex_alloc(matrix_a.rows, matrix_a.cols))
    data_result = ctypes.cast(result._matrix.data, ctypes.POINTER(gsl_complex))
    data_a = ctypes.cast(matrix_a._matrix.data, ctypes.POINTER(gsl_complex))
    data_b = ctypes.cast(matrix_b._matrix.data, ctypes.POINTER(gsl_complex))
    for i in range(matrix_a.rows * matrix_a.cols):
        data_result[i].real = data_a[i].real + data_b[i].real
        data_result[i].imag = data_a[i].imag + data_b[i].imag
    return result


def gsl_to_list(matrix):
    result = []
    for i in range(matrix.rows):
        row = []
        for j in range(matrix.cols):
            idx = i * matrix.cols + j
            z = complex(matrix._matrix.data[idx].real, matrix._matrix.data[idx].imag)
            row.append(z)
        result.append(row)
    return result


